// Isolated browser fixture; never contacts Clerk, Supabase, Twilio or production.
import {build} from 'esbuild';
import {createServer} from 'node:http';
import {resolve} from 'node:path';
const root=resolve(process.env.E2_PROJECT_ROOT||'../E2local-main');
const mock=`import React,{createContext,useContext,useState} from 'react';
export const Context=createContext({ready:true,identity:'fixture:one',revision:'one'});
const business={id:'one',name:'Bello Home Services',description:'Home repairs and maintenance, with a helpful team ready to take your call.',contactEmail:'hello@example.test',contactPhone:'+13035550123',services:['Door repairs','General maintenance'],serviceAreas:['Denver','Aurora'],timeZone:'America/Denver',agents:[{id:'alex',name:'Alex',phone:'+18775550180'}]};
const second={...business,id:'two',name:'Mountain Cleaning',services:['Residential cleaning'],agents:[{id:'sam',name:'Sam',phone:'+18775550181'}]};
const call={id:'12345678-1234-1234-1234-123456789012',businessId:'one',agentId:'alex',caller:'+13035550123',startedAt:'2026-10-11T18:15:00Z',endedAt:'2026-10-11T18:18:00Z',durationSeconds:180,status:'completed',outcome:'Follow-up requested',summary:'Caller asked about repairing a front door and requested a visit next week.',expiresAt:'2099-01-01T00:00:00Z',recordingState:'ready'};
export function useDashboardBoundary(){return useContext(Context);}
export function useDashboardResource(key){const context=useContext(Context);const params=new URLSearchParams(key.split('?')[1]);const tenant=params.get('business')||'one';
 const calls=tenant==='two'?[]:[call,{...call,id:'22345678-1234-1234-1234-123456789012',status:'failed',durationSeconds:0,recordingState:'expired',expiresAt:'2020-01-01',summary:'Call ended before an agent could respond.'}];
 let data=key==='voice'?{businesses:context.ready?[business,second]:[]}:key.startsWith('voice-calls?')?{businessId:tenant,rows:calls.filter(c=>(!params.get('status')||params.get('status')===c.status)&&(!params.get('q')||c.summary.toLowerCase().includes(params.get('q').toLowerCase()))),total:calls.length,page:1,pageSize:25}:{...calls.find(c=>c.id===params.get('id')),transcript:[{role:'assistant',text:'Hello, how can I help you today?'},{role:'user',text:'I would like to have my front door repaired.'}]};
 return {data,identity:context.identity};}
export const DashboardDataMessage=()=>React.createElement('p',null,'Loading…');
export function Fixture({children}){const [ready,setReady]=useState(true);return React.createElement(Context.Provider,{value:{ready,identity:'fixture:'+ready,revision:'one'}},React.createElement('aside',null,'Local fixture · synthetic data ',React.createElement('button',{onClick:()=>setReady(!ready)},ready?'Hide service':'Release service')),children);}
`;
const result=await build({stdin:{contents:`import React from 'react';import {createRoot} from 'react-dom/client';import {VoiceView} from './app/dashboard/voice/voice-view';import {Fixture} from 'voice-fixture';createRoot(document.getElementById('root')).render(<Fixture><VoiceView /></Fixture>);`,loader:'tsx',resolveDir:root},bundle:true,write:false,outfile:'voice.js',jsx:'automatic',alias:{'@':root,react:resolve(root,'node_modules/react'),'react-dom':resolve(root,'node_modules/react-dom')},plugins:[{name:'voice-fixture',setup(b){b.onResolve({filter:/dashboard-cache$|^voice-fixture$/},()=>({path:'voice-fixture',namespace:'fixture'}));b.onLoad({filter:/.*/,namespace:'fixture'},()=>({contents:mock,loader:'js',resolveDir:root}));}}]});
const js=result.outputFiles.find(f=>f.path.endsWith('.js')).text,css=result.outputFiles.find(f=>f.path.endsWith('.css')).text;
const html=`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Voice preview</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#182c43;font-family:Arial,sans-serif}main{max-width:1150px;margin:0 auto;padding:32px}aside{margin-bottom:24px;font-size:12px;color:#687384}button{font:inherit}@media(max-width:600px){main{padding:16px}}</style><link rel="stylesheet" href="/voice.css"></head><body><main id="root"></main><script src="/voice.js"></script></body></html>`;
const wav=Buffer.alloc(44+16000);wav.write('RIFF',0);wav.writeUInt32LE(wav.length-8,4);wav.write('WAVEfmt ',8);wav.writeUInt32LE(16,16);wav.writeUInt16LE(1,20);wav.writeUInt16LE(1,22);wav.writeUInt32LE(8000,24);wav.writeUInt32LE(16000,28);wav.writeUInt16LE(2,32);wav.writeUInt16LE(16,34);wav.write('data',36);wav.writeUInt32LE(16000,40);
const server=createServer((req,res)=>{if(req.url==='/fixture.wav'){res.setHeader('Content-Type','audio/wav');res.end(wav);return;}if(req.url.startsWith('/api/')){res.writeHead(200,{'Content-Type':'application/json'});res.end(JSON.stringify({url:'/fixture.wav',expiresAt:new Date(Date.now()+300000).toISOString()}));return;}res.setHeader('Content-Type',req.url==='/voice.js'?'text/javascript':req.url==='/voice.css'?'text/css':'text/html');res.end(req.url==='/voice.js'?js:req.url==='/voice.css'?css:html);});
server.listen(8188,'127.0.0.1',()=>console.log('Voice fixture http://127.0.0.1:8188'));
